CREATE TABLE IF NOT EXISTS providers (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  base_url TEXT NOT NULL,
  auth_type TEXT NOT NULL,
  protocol TEXT NOT NULL,
  description TEXT,
  keyless INTEGER NOT NULL DEFAULT 0,
  key_hint TEXT,
  extra_headers TEXT,
  force_single_tool_call INTEGER,
  model_identity TEXT,
  model_aliases TEXT,
  electron_hub_proxy_error INTEGER,
  ensure_done INTEGER,
  limits TEXT
);

CREATE INDEX IF NOT EXISTS idx_providers_keyless ON providers(keyless);

